-- Bibliothèque d'exercices et de recettes, éditable depuis l'espace admin.
-- Étape 1 : exécuter d'abord la création des tables et politiques ci-dessous.
-- Étape 2 : les INSERT en bas de fichier importent la base de départ.

create table if not exists exercices (
  id uuid primary key default gen_random_uuid(),
  created_at timestamptz not null default now(),
  nom text not null,
  zone text not null,
  niveau int not null default 0,
  materiel int not null default 0,
  type text not null default 'renfo',
  contre_indications jsonb default '[]',
  format text
);
alter table exercices enable row level security;
drop policy if exists "authenticated full access" on exercices;
create policy "authenticated full access" on exercices for all using (auth.role() = 'authenticated') with check (auth.role() = 'authenticated');

create table if not exists recettes (
  id uuid primary key default gen_random_uuid(),
  created_at timestamptz not null default now(),
  nom text not null,
  repas text not null,
  profils jsonb default '[]',
  vegetarien boolean default false,
  vegan boolean default false,
  sans_gluten boolean default false,
  sans_lactose boolean default false,
  contient jsonb default '[]',
  proteines_g int,
  ingredients jsonb default '[]',
  etapes jsonb default '[]'
);
alter table recettes enable row level security;
drop policy if exists "authenticated full access" on recettes;
create policy "authenticated full access" on recettes for all using (auth.role() = 'authenticated') with check (auth.role() = 'authenticated');

-- Nouveaux champs sur les fiches clientes : exercices préférés à privilégier,
-- temps prévu pour manger avant le travail, et mots-clés libres à éviter.
alter table clientes add column if not exists exercices_preferes jsonb default '[]';
alter table clientes add column if not exists tampon_repas int default 60;
alter table clientes add column if not exists aliments_evites_libre jsonb default '[]';

