insert into recettes (nom, repas, profils, vegetarien, vegan, sans_gluten, sans_lactose, contient, proteines_g, ingredients, etapes) values ('Poulet grillé, riz complet, brocolis', 'dejeuner_diner', '["tonus","prise_masse","perte_poids"]'::jsonb, false, false, true, true, '[]'::jsonb, 38, '[{"nom":"blanc de poulet","quantite":150,"unite":"g"},{"nom":"riz complet","quantite":80,"unite":"g"},{"nom":"brocolis","quantite":150,"unite":"g"}]'::jsonb, '["Laver et couper tous les légumes en une seule fois pour toute la semaine : brocolis.","Cuire la source de protéine en grande quantité (poêle, plancha ou four) : blanc de poulet.","Cuire le féculent en grande quantité (casserole ou autocuiseur) : riz complet.","Assaisonner l''ensemble, puis répartir en portions individuelles dans des contenants hermétiques.","Réfrigérer jusqu''à 4 jours, ou congeler les portions en trop pour plus tard."]'::jsonb);
